import React from 'react';
import { isElement } from 'react-is';

import { TooltipInfoContent } from '../section-components/TooltipInfoContent.js';
import { TooltipSymbolContent } from '../section-components/TooltipSymbolContent.js';
import { TooltipValueContent } from '../section-components/TooltipValueContent.js';
import { TooltipItemSlots } from '../types/ChartTooltip.config.js';

export const iterateTooltipItemSlots = (children: React.ReactNode) => {
  const slots: TooltipItemSlots = {};

  React.Children.forEach(children, (child) => {
    if (isElement(child)) {
      switch (child.type) {
        case TooltipSymbolContent: {
          slots.symbolSection = child;
          break;
        }
        case TooltipInfoContent: {
          slots.infoSection = child;
          break;
        }
        case TooltipValueContent: {
          slots.valueSection = child;
          break;
        }
      }
    }
  });

  return slots;
};
